\coordinate (O) at (4.041,0);
\coordinate (T) at (3.031,1.75);
\coordinate (Q) at (3.031,-1.75);
\draw (O) circle (2.021);
\fill (O) circle (1.5pt);
\node[below] at (O) {$O$};
\draw[tickmark] (P) -- (T);
\draw[tickmark] (P) -- (Q);
\draw (T) -- (Q);
\node[left] at (P) {$P$};
\node[above] at (T) {$T$};
\node[below] at (Q) {$Q$};
